import{_ as r,a0 as a,w as n,s as l,ao as d,I as p,x as e,a1 as o,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"我的第一個系統管理員錯誤 | LCTT x X-CMD","titleTemplate":false,"description":"我的第一個系統管理員錯誤 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我的第一個系統管理員錯誤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我的第一個系統管理員錯誤 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20180702 My first sysadmin mistake","title":"我的第一個系統管理員錯誤","tag":"201807","desc":""},"relativePath":"201807/20180702 My first sysadmin mistake.md","filePath":"[post].md"}'),m={name:"201807/20180702 My first sysadmin mistake.md"};function u(f,t,T,k,x,C){const s=a("Link");return n(),l("div",null,[t[15]||(t[15]=d('<h1 id="我的第一個系統管理員錯誤" tabindex="-1">我的第一個系統管理員錯誤 <a class="header-anchor" href="#我的第一個系統管理員錯誤" aria-label="Permalink to “我的第一個系統管理員錯誤”">​</a></h1><blockquote><p>如何在崩潰的局面中集中精力尋找解決方案。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/BUSINESS_mistakes.png?itok=dN0OoIl5" alt=""></p><p>如果你在 IT 領域工作，你知道事情永遠不會像你想像的那樣完好。在某些時候，你會遇到錯誤或出現問題，你最終必須解決問題。這就是系統管理員的工作。</p><p>作為人類，我們都會犯錯誤。我們不是已經犯錯，就是即將犯錯。結果，我們最終還必須解決自己的錯誤。總是這樣。我們都會失誤、敲錯字母或犯錯。</p><p>作為一名年輕的系統管理員，我艱難地學到了這一課。我犯了一個大錯。但是多虧了上級的指導，我學會了不去糾纏於我的錯誤，而是制定一個“錯誤策略”來做正確的事情。從錯誤中吸取教訓。克服它，繼續前進。</p><p>我的第一份工作是一家小公司的 Unix 系統管理員。真的，我是一名生嫩的系統管理員，但我大部分時間都獨自工作。我們是一個小型 IT 團隊，只有我們三個人。我是 20 或 30 台 Unix 工作站和服務器的唯一系統管理員。另外兩個支持 Windows 服務器和桌面。</p><p>任何閲讀這篇文章的系統管理員都不會對此感到意外，作為一個不成熟的初級系統管理員，我最終在錯誤的目錄中運行了 <code>rm</code> 命令——作為 root 用户。我以為我正在為我們的某個程序刪除一些陳舊的緩存文件。相反，我錯誤地清除了 <code>/etc</code> 目錄中的所有文件。糟糕。</p><p>我意識到犯了錯誤是看到了一條錯誤消息，“<code>rm</code> 無法刪除某些子目錄”。但緩存目錄應該只包含文件！我立即停止了 <code>rm</code> 命令，看看我做了什麼。然後我驚慌失措。一下子，無數個想法湧入了我的腦中。我剛剛銷燬了一台重要的服務器嗎？系統會怎麼樣？我會被解僱嗎？</p><p>幸運的是，我運行的是 <code>rm *</code> 而不是 <code>rm -rf *</code>，因此我只刪除了文件。子目錄仍在那裏。但這並沒有讓我感覺更好。</p><p>我立刻去找我的主管告訴她我做了什麼。她看到我對自己的錯誤感到愚蠢，但這是我犯的。儘管緊迫，她花了幾分鐘時間跟我做了一些指導。她説：“你不是第一個這樣做的人，在你這種情況下，別人會怎麼做？”這幫助我平靜下來並專注。我開始更少考慮我剛剛做的愚蠢事情，而更多地考慮我接下來要做的事情。</p><p>我做了一個簡單的策略：不要重啓服務器。使用相同的系統作為模板，並重建 <code>/etc</code> 目錄。</p><p>制定了行動計劃後，剩下的就很容易了。只需運行正確的命令即可從另一台服務器複製 <code>/etc</code> 文件並編輯配置，使其與系統匹配。多虧了我對所有東西都做記錄的習慣，我使用已有的文檔進行最後的調整。我避免了完全恢復服務器，這意味着一個巨大的宕機事件。</p><p>可以肯定的是，我從這個錯誤中吸取了教訓。在接下來作為系統管理員的日子中，我總是在運行任何命令之前確認我所在的目錄。</p><p>我還學習了構建“錯誤策略”的價值。當事情出錯時，恐慌並思考接下來可能發生的所有壞事是很自然的。這是人性。但是制定一個“錯誤策略”可以幫助我不再擔心出了什麼問題，而是專注於讓事情變得更好。我仍然會想一下，但是知道我接下來的步驟可以讓我“克服它”。</p><hr>',16)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),o(s,{href:"https://opensource.com/article/18/7/my-first-sysadmin-mistake"},{default:i(()=>[...t[0]||(t[0]=[e("https://opensource.com/article/18/7/my-first-sysadmin-mistake",-1)])]),_:1})]),p("p",null,[t[6]||(t[6]=e("作者：",-1)),o(s,{href:"https://opensource.com/users/jim-hall"},{default:i(()=>[...t[2]||(t[2]=[e("Jim Hall",-1)])]),_:1}),t[7]||(t[7]=e(" 選題：",-1)),o(s,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[3]||(t[3]=[e("lujun9972",-1)])]),_:1}),t[8]||(t[8]=e(" 譯者：",-1)),o(s,{href:"https://github.com/geekpi"},{default:i(()=>[...t[4]||(t[4]=[e("geekpi",-1)])]),_:1}),t[9]||(t[9]=e(" 校對：",-1)),o(s,{href:"https://github.com/wxy"},{default:i(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[12]||(t[12]=e("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原創編譯，",-1)),o(s,{href:"https://linux.cn/"},{default:i(()=>[...t[11]||(t[11]=[e("Linux中國",-1)])]),_:1}),t[14]||(t[14]=e(" 榮譽推出",-1))])])}const b=r(m,[["render",u]]);export{L as __pageData,b as default};
